import React from "react";
import { BrowserRouter, Routes, Route } from "react-router-dom"; 

import Home from "./Pages/Home";
import Navbar from "./Component/Navbar";
 function App() {
  return (
     <BrowserRouter>
     <Navbar/>
      <Routes>
        <Route path="/" element={<Home/>} />

      </Routes>
    </BrowserRouter>
  )
}
export default App;
